-- Bluestock Mutual Fund Analytics schema
CREATE TABLE dim_fund (amfi_code INTEGER PRIMARY KEY, fund_house TEXT, scheme_name TEXT, category TEXT, sub_category TEXT, plan TEXT, launch_date TEXT, benchmark TEXT);
CREATE TABLE fact_nav (amfi_code INTEGER, date TEXT, nav REAL, PRIMARY KEY (amfi_code, date));
CREATE TABLE fact_performance (amfi_code INTEGER PRIMARY KEY, scheme_name TEXT, fund_house TEXT, category TEXT, plan TEXT, return_1yr_pct REAL, return_3yr_pct REAL, return_5yr_pct REAL, benchmark_3yr_pct REAL, alpha REAL, beta REAL, sharpe_ratio REAL, sortino_ratio REAL, std_dev_ann_pct REAL, max_drawdown_pct REAL, aum_crore REAL, expense_ratio_pct REAL, morningstar_rating INTEGER, risk_grade TEXT);
CREATE TABLE fact_transactions (transaction_id INTEGER PRIMARY KEY, investor_id TEXT, transaction_date TEXT, amfi_code INTEGER, transaction_type TEXT, amount_inr REAL, state TEXT, city TEXT, city_tier TEXT, age_group TEXT, gender TEXT, annual_income_lakh REAL, payment_mode TEXT, kyc_status TEXT);
